// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import {BaseTest} from "./BaseTest.t.sol";
import {ClaimIssuerManager} from "../src/identity/ClaimIssuerManager.sol";
import {IAccessControl} from "@openzeppelin/contracts/access/IAccessControl.sol";

contract ClaimIssuerManagerTest is BaseTest {
    address internal issuer = makeAddr("issuer");
    address internal factory2 = makeAddr("factory2");

    uint256[] internal singleClaim;
    uint256[] internal multiClaims;

    function setUp() public override {
        super.setUp();
        singleClaim = new uint256[](1);
        singleClaim[0] = 42;

        multiClaims = new uint256[](3);
        multiClaims[0] = 10;
        multiClaims[1] = 20;
        multiClaims[2] = 30;
    }

    // --- addClaimIssuer ---

    function test_addClaimIssuer() public {
        vm.prank(admin);
        claimIssuerManager.addClaimIssuer(issuer, singleClaim);

        assertTrue(claimIssuerManager.activeClaimIssuers(issuer));
        assertTrue(claimIssuerManager.isValidClaim(issuer, 42));
    }

    function test_addClaimIssuer_emitsEvent() public {
        vm.expectEmit(true, false, false, true, address(claimIssuerManager));
        emit ClaimIssuerManager.ClaimIssuerAdded(issuer, singleClaim);
        vm.prank(admin);
        claimIssuerManager.addClaimIssuer(issuer, singleClaim);
    }

    function test_addClaimIssuer_revertsIfNotAdmin() public {
        vm.expectRevert(abi.encodeWithSelector(
            IAccessControl.AccessControlUnauthorizedAccount.selector,
            alice,
            claimIssuerManager.CLAIM_ISSUER_ADMIN()
        ));
        vm.prank(alice);
        claimIssuerManager.addClaimIssuer(issuer, singleClaim);
    }

    function test_addClaimIssuer_revertsIfZeroAddress() public {
        vm.expectRevert(abi.encodeWithSelector(
            ClaimIssuerManager.InvalidAddress.selector,
            "Issuer cannot be zero address"
        ));
        vm.prank(admin);
        claimIssuerManager.addClaimIssuer(address(0), singleClaim);
    }

    function test_addClaimIssuer_revertsIfEmptyArray() public {
        uint256[] memory empty = new uint256[](0);
        vm.expectRevert(ClaimIssuerManager.InvalidArray.selector);
        vm.prank(admin);
        claimIssuerManager.addClaimIssuer(issuer, empty);
    }

    // --- removeClaimIssuer ---

    function test_removeClaimIssuer() public {
        vm.startPrank(admin);
        claimIssuerManager.addClaimIssuer(issuer, singleClaim);
        claimIssuerManager.removeClaimIssuer(issuer);
        vm.stopPrank();

        assertFalse(claimIssuerManager.activeClaimIssuers(issuer));
        assertFalse(claimIssuerManager.isValidClaim(issuer, 42));
    }

    function test_removeClaimIssuer_emitsEvent() public {
        vm.prank(admin);
        claimIssuerManager.addClaimIssuer(issuer, singleClaim);

        vm.expectEmit(true, false, false, false, address(claimIssuerManager));
        emit ClaimIssuerManager.ClaimIssuerRemoved(issuer);
        vm.prank(admin);
        claimIssuerManager.removeClaimIssuer(issuer);
    }

    function test_removeClaimIssuer_revertsIfNotAdmin() public {
        vm.expectRevert(abi.encodeWithSelector(
            IAccessControl.AccessControlUnauthorizedAccount.selector,
            alice,
            claimIssuerManager.CLAIM_ISSUER_ADMIN()
        ));
        vm.prank(alice);
        claimIssuerManager.removeClaimIssuer(issuer);
    }

    // --- addClaimToIssuer / removeClaimFromIssuer ---

    function test_addClaimToIssuer() public {
        vm.startPrank(admin);
        claimIssuerManager.addClaimIssuer(issuer, singleClaim);
        claimIssuerManager.addClaimToIssuer(issuer, 99);
        vm.stopPrank();

        assertTrue(claimIssuerManager.possibleClaims(issuer, 99));
    }

    function test_removeClaimFromIssuer() public {
        vm.startPrank(admin);
        claimIssuerManager.addClaimIssuer(issuer, singleClaim);
        claimIssuerManager.removeClaimFromIssuer(issuer, 42);
        vm.stopPrank();

        assertFalse(claimIssuerManager.possibleClaims(issuer, 42));
    }

    // --- batchAddClaimToIssuer / batchRemoveClaimFromIssuer ---

    function test_batchAddClaimToIssuer() public {
        vm.startPrank(admin);
        claimIssuerManager.addClaimIssuer(issuer, singleClaim);
        claimIssuerManager.batchAddClaimToIssuer(issuer, multiClaims);
        vm.stopPrank();

        assertTrue(claimIssuerManager.possibleClaims(issuer, 10));
        assertTrue(claimIssuerManager.possibleClaims(issuer, 20));
        assertTrue(claimIssuerManager.possibleClaims(issuer, 30));
    }

    function test_batchAddClaimToIssuer_revertsIfEmptyArray() public {
        uint256[] memory empty = new uint256[](0);
        vm.expectRevert(ClaimIssuerManager.InvalidArray.selector);
        vm.prank(admin);
        claimIssuerManager.batchAddClaimToIssuer(issuer, empty);
    }

    function test_batchRemoveClaimFromIssuer() public {
        vm.startPrank(admin);
        claimIssuerManager.addClaimIssuer(issuer, multiClaims);
        claimIssuerManager.batchRemoveClaimFromIssuer(issuer, multiClaims);
        vm.stopPrank();

        assertFalse(claimIssuerManager.possibleClaims(issuer, 10));
        assertFalse(claimIssuerManager.possibleClaims(issuer, 20));
        assertFalse(claimIssuerManager.possibleClaims(issuer, 30));
    }

    function test_batchRemoveClaimFromIssuer_revertsIfEmptyArray() public {
        uint256[] memory empty = new uint256[](0);
        vm.expectRevert(ClaimIssuerManager.InvalidArray.selector);
        vm.prank(admin);
        claimIssuerManager.batchRemoveClaimFromIssuer(issuer, empty);
    }

    // --- addTokenFactory / removeTokenFactory ---

    function test_addTokenFactory() public {
        vm.prank(admin);
        claimIssuerManager.addTokenFactory(factory2);

        assertTrue(claimIssuerManager.isTokenFactory(factory2));
    }

    function test_addTokenFactory_emitsEvent() public {
        vm.expectEmit(true, false, false, false, address(claimIssuerManager));
        emit ClaimIssuerManager.TokenFactoryAdded(factory2);
        vm.prank(admin);
        claimIssuerManager.addTokenFactory(factory2);
    }

    function test_addTokenFactory_revertsIfDuplicate() public {
        vm.startPrank(admin);
        claimIssuerManager.addTokenFactory(factory2);
        vm.expectRevert(ClaimIssuerManager.TokenFactoryAlreadyAdded.selector);
        claimIssuerManager.addTokenFactory(factory2);
        vm.stopPrank();
    }

    function test_removeTokenFactory() public {
        vm.startPrank(admin);
        claimIssuerManager.addTokenFactory(factory2);
        claimIssuerManager.removeTokenFactory(factory2);
        vm.stopPrank();

        assertFalse(claimIssuerManager.isTokenFactory(factory2));
    }

    function test_removeTokenFactory_revertsIfNotAdded() public {
        vm.expectRevert(ClaimIssuerManager.TokenFactoryNotAdded.selector);
        vm.prank(admin);
        claimIssuerManager.removeTokenFactory(factory2);
    }

    function test_getTokenFactories() public view {
        address[] memory factories = claimIssuerManager.getTokenFactories();
        assertEq(factories.length, 1);
        assertEq(factories[0], address(tokenFactory));
    }

    // --- isValidClaim ---

    function test_isValidClaim_tokenFactoryAlwaysValid() public view {
        // Token factory is trusted for any claim ID, no need to be an active issuer
        assertTrue(claimIssuerManager.isValidClaim(address(tokenFactory), 9999));
    }

    function test_isValidClaim_activeIssuerWithClaim() public {
        vm.prank(admin);
        claimIssuerManager.addClaimIssuer(issuer, singleClaim);

        assertTrue(claimIssuerManager.isValidClaim(issuer, 42));
    }

    function test_isValidClaim_inactiveIssuerReturnsFalse() public {
        vm.startPrank(admin);
        claimIssuerManager.addClaimIssuer(issuer, singleClaim);
        claimIssuerManager.removeClaimIssuer(issuer);
        vm.stopPrank();

        assertFalse(claimIssuerManager.isValidClaim(issuer, 42));
    }

    function test_isValidClaim_wrongClaimReturnsFalse() public {
        vm.prank(admin);
        claimIssuerManager.addClaimIssuer(issuer, singleClaim);

        assertFalse(claimIssuerManager.isValidClaim(issuer, 9999));
    }

    function test_isValidClaim_unknownIssuerReturnsFalse() public view {
        assertFalse(claimIssuerManager.isValidClaim(alice, 42));
    }
}

test/Token.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import {BaseTest} from "./BaseTest.t.sol";
import {Token} from "../src/Token.sol";
import {Gorra} from "../src/identity/Gorra.sol";
import {Identity} from "../src/identity/Identity.sol";
import {IAccessControl} from "@openzeppelin/contracts/access/IAccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ERC20Freezable} from "@openzeppelin/community-contracts/token/ERC20/extensions/ERC20Freezable.sol";

contract TokenTest is BaseTest {
    // --- Constructor / Roles ---

    function test_rolesGranted() public view {
        assertTrue(token.hasRole(token.PAUSER_ROLE(), enforcer));
        assertTrue(token.hasRole(token.MINTER_ROLE(), enforcer));
        assertTrue(token.hasRole(token.BURNER_ROLE(), enforcer));
        assertTrue(token.hasRole(token.FREEZER_ROLE(), enforcer));
        assertTrue(token.hasRole(token.ENFORCER_ROLE(), enforcer));
    }

    function test_adminIsDefaultAdmin() public view {
        assertTrue(token.hasRole(token.DEFAULT_ADMIN_ROLE(), admin));
    }

    function test_emptyName_reverts() public {
        uint256[] memory claims = new uint256[](0);
        vm.expectRevert(abi.encodeWithSelector(Token.EmptyString.selector, "Token name cannot be empty"));
        new Token("", "RWA", admin, enforcer, address(identityFactory), claims);
    }

    function test_emptySymbol_reverts() public {
        uint256[] memory claims = new uint256[](0);
        vm.expectRevert(abi.encodeWithSelector(Token.EmptyString.selector, "Token symbol cannot be empty"));
        new Token("RWA Token", "", admin, enforcer, address(identityFactory), claims);
    }

    function test_claimsArrayTooLarge_reverts() public {
        uint256[] memory bigClaims = new uint256[](101);
        vm.expectRevert(Gorra.InvalidArray.selector);
        new Token("RWA Token", "RWA", admin, enforcer, address(identityFactory), bigClaims);
    }

    function test_zeroDefaultAdmin_reverts() public {
        uint256[] memory claims = new uint256[](0);
        vm.expectRevert(abi.encodeWithSelector(Gorra.InvalidAddress.selector, "Default admin cannot be zero address"));
        new Token("RWA Token", "RWA", address(0), enforcer, address(identityFactory), claims);
    }

    function test_zeroEnforcer_reverts() public {
        uint256[] memory claims = new uint256[](0);
        vm.expectRevert(abi.encodeWithSelector(Gorra.InvalidAddress.selector, "Enforcer cannot be zero address"));
        new Token("RWA Token", "RWA", admin, address(0), address(identityFactory), claims);
    }

    // --- Mint ---

    function test_mint_success() public {
        _setupIdentityWithClaim(alice);

        vm.prank(enforcer);
        token.mint(alice, 100e18);

        assertEq(token.balanceOf(alice), 100e18);
    }

    function test_mint_emitsEvent() public {
        _setupIdentityWithClaim(alice);

        vm.expectEmit(true, true, false, true, address(token));
        emit Token.TokenMinted(alice, 100e18, enforcer);
        vm.prank(enforcer);
        token.mint(alice, 100e18);
    }

    function test_mint_revertsIfNotMinter() public {
        _setupIdentityWithClaim(alice);

        vm.expectRevert(abi.encodeWithSelector(
            IAccessControl.AccessControlUnauthorizedAccount.selector,
            alice,
            token.MINTER_ROLE()
        ));
        vm.prank(alice);
        token.mint(alice, 100e18);
    }

    function test_mint_revertsIfZeroAmount() public {
        _setupIdentityWithClaim(alice);

        vm.expectRevert(abi.encodeWithSelector(Token.InvalidAmount.selector, "Cannot mint zero amount"));
        vm.prank(enforcer);
        token.mint(alice, 0);
    }

    function test_mint_revertsIfRecipientHasNoIdentity() public {
        vm.expectRevert(abi.encodeWithSelector(
            Gorra.InvalidAddress.selector,
            "Recipient has no identity"
        ));
        vm.prank(enforcer);
        token.mint(charlie, 100e18);
    }

    function test_mint_revertsIfRecipientMissingClaim() public {
        // alice has identity but no KYC claim
        vm.prank(admin);
        identityFactory.createIdentity(alice);

        vm.expectRevert(Gorra.InsufficientPermissions.selector);
        vm.prank(enforcer);
        token.mint(alice, 100e18);
    }

    // --- Burn ---

    function test_burn_success() public {
        _setupIdentityWithClaim(alice);
        vm.prank(enforcer);
        token.mint(alice, 100e18);

        vm.prank(alice);
        token.burn(40e18);

        assertEq(token.balanceOf(alice), 60e18);
    }

    function test_burn_emitsEvent() public {
        _setupIdentityWithClaim(alice);
        vm.prank(enforcer);
        token.mint(alice, 100e18);

        vm.expectEmit(true, true, false, true, address(token));
        emit Token.TokenBurned(alice, 40e18, alice);
        vm.prank(alice);
        token.burn(40e18);
    }

    function test_burn_revertsIfZeroAmount() public {
        _setupIdentityWithClaim(alice);
        vm.prank(enforcer);
        token.mint(alice, 100e18);

        vm.expectRevert(abi.encodeWithSelector(Token.InvalidAmount.selector, "Cannot burn zero amount"));
        vm.prank(alice);
        token.burn(0);
    }

    // --- BurnFrom ---

    function test_burnFrom_success() public {
        _setupIdentityWithClaim(alice);
        vm.prank(enforcer);
        token.mint(alice, 100e18);

        vm.prank(alice);
        token.approve(enforcer, 50e18);

        vm.prank(enforcer);
        token.burnFrom(alice, 50e18);

        assertEq(token.balanceOf(alice), 50e18);
    }

    function test_burnFrom_emitsEvent() public {
        _setupIdentityWithClaim(alice);
        vm.prank(enforcer);
        token.mint(alice, 100e18);
        vm.prank(alice);
        token.approve(enforcer, 50e18);

        vm.expectEmit(true, true, false, true, address(token));
        emit Token.TokenBurned(alice, 50e18, enforcer);
        vm.prank(enforcer);
        token.burnFrom(alice, 50e18);
    }

    function test_burnFrom_revertsIfNotBurner() public {
        _setupIdentityWithClaim(alice);
        vm.prank(enforcer);
        token.mint(alice, 100e18);
        vm.prank(alice);
        token.approve(bob, 50e18);

        vm.expectRevert(abi.encodeWithSelector(
            IAccessControl.AccessControlUnauthorizedAccount.selector,
            bob,
            token.BURNER_ROLE()
        ));
        vm.prank(bob);
        token.burnFrom(alice, 50e18);
    }

    // --- Pause ---

    function test_pause_success() public {
        vm.prank(enforcer);
        token.pause();

        assertTrue(token.paused());
    }

    function test_pause_revertsIfNotPauser() public {
        vm.expectRevert(abi.encodeWithSelector(
            IAccessControl.AccessControlUnauthorizedAccount.selector,
            alice,
            token.PAUSER_ROLE()
        ));
        vm.prank(alice);
        token.pause();
    }

    function test_unpause_success() public {
        vm.startPrank(enforcer);
        token.pause();
        token.unpause();
        vm.stopPrank();

        assertFalse(token.paused());
    }

    function test_transfer_revertsWhenPaused() public {
        _setupIdentityWithClaim(alice);
        _setupIdentityWithClaim(bob);
        vm.prank(enforcer);
        token.mint(alice, 100e18);

        vm.prank(enforcer);
        token.pause();

        vm.expectRevert(Pausable.EnforcedPause.selector);
        vm.prank(alice);
        token.transfer(bob, 10e18);
    }

    // --- Transfer (Gorra gates) ---

    function test_transfer_success() public {
        _setupIdentityWithClaim(alice);
        _setupIdentityWithClaim(bob);
        vm.prank(enforcer);
        token.mint(alice, 100e18);

        vm.prank(alice);
        token.transfer(bob, 30e18);

        assertEq(token.balanceOf(alice), 70e18);
        assertEq(token.balanceOf(bob), 30e18);
    }

    function test_transfer_revertsIfSenderNoIdentity() public {
        // Mint to alice while she has identity+claim, then unlink her
        _setupIdentityWithClaim(alice);
        vm.prank(enforcer);
        token.mint(alice, 100e18);

        _setupIdentityWithClaim(bob);

        vm.prank(admin);
        identityFactory.unlinkWallet(alice);

        vm.expectRevert(abi.encodeWithSelector(
            Gorra.InvalidAddress.selector,
            "Sender has no identity"
        ));
        vm.prank(alice);
        token.transfer(bob, 10e18);
    }

    function test_transfer_revertsIfRecipientNoIdentity() public {
        _setupIdentityWithClaim(alice);
        vm.prank(enforcer);
        token.mint(alice, 100e18);

        // charlie has no identity
        vm.expectRevert(abi.encodeWithSelector(
            Gorra.InvalidAddress.selector,
            "Recipient has no identity"
        ));
        vm.prank(alice);
        token.transfer(charlie, 10e18);
    }

    function test_transfer_revertsIfSenderMissingClaim() public {
        // Give alice identity + claim to mint, then strip the claim
        address aliceIdentity = _setupIdentityWithClaim(alice);
        vm.prank(enforcer);
        token.mint(alice, 100e18);

        vm.prank(admin);
        Identity(aliceIdentity).removeClaim(CLAIM_KYC);

        _setupIdentityWithClaim(bob);

        vm.expectRevert(Gorra.InsufficientPermissions.selector);
        vm.prank(alice);
        token.transfer(bob, 10e18);
    }

    function test_transfer_revertsIfRecipientMissingClaim() public {
        _setupIdentityWithClaim(alice);
        vm.prank(enforcer);
        token.mint(alice, 100e18);

        // bob has identity but no claims
        vm.prank(admin);
        identityFactory.createIdentity(bob);

        vm.expectRevert(Gorra.InsufficientPermissions.selector);
        vm.prank(alice);
        token.transfer(bob, 10e18);
    }

    // --- Freeze (ERC20uRWA / ERC20Freezable) ---

    function test_freeze_blocksTransfer() public {
        _setupIdentityWithClaim(alice);
        _setupIdentityWithClaim(bob);
        vm.prank(enforcer);
        token.mint(alice, 100e18);

        vm.prank(enforcer);
        token.setFrozenTokens(alice, 100e18);

        assertEq(token.frozen(alice), 100e18);
        assertEq(token.available(alice), 0);

        vm.expectRevert(abi.encodeWithSelector(
            ERC20Freezable.ERC20InsufficientUnfrozenBalance.selector,
            alice,
            1,
            0
        ));
        vm.prank(alice);
        token.transfer(bob, 1);
    }

    function test_unfreeze_restoresTransfer() public {
        _setupIdentityWithClaim(alice);
        _setupIdentityWithClaim(bob);
        vm.prank(enforcer);
        token.mint(alice, 100e18);

        vm.prank(enforcer);
        token.setFrozenTokens(alice, 100e18);

        vm.prank(enforcer);
        token.setFrozenTokens(alice, 0);

        vm.prank(alice);
        token.transfer(bob, 50e18);

        assertEq(token.balanceOf(bob), 50e18);
    }

    // --- Required Claims ---

    function test_setRequiredClaims() public {
        uint256[] memory newClaims = new uint256[](2);
        newClaims[0] = 1;
        newClaims[1] = 2;

        vm.prank(admin);
        token.setRequiredClaims(newClaims);

        uint256[] memory stored = token.getRequiredClaims();
        assertEq(stored.length, 2);
        assertEq(stored[0], 1);
        assertEq(stored[1], 2);
    }

    function test_setRequiredClaims_emitsEvent() public {
        uint256[] memory oldClaims = token.getRequiredClaims();
        uint256[] memory newClaims = new uint256[](0);

        vm.expectEmit(false, false, false, true, address(token));
        emit Gorra.RequiredClaimsUpdated(oldClaims, newClaims);
        vm.prank(admin);
        token.setRequiredClaims(newClaims);
    }

    function test_setRequiredClaims_revertsIfNotAdmin() public {
        uint256[] memory newClaims = new uint256[](0);
        vm.expectRevert(abi.encodeWithSelector(
            IAccessControl.AccessControlUnauthorizedAccount.selector,
            alice,
            token.DEFAULT_ADMIN_ROLE()
        ));
        vm.prank(alice);
        token.setRequiredClaims(newClaims);
    }

    function test_setRequiredClaims_revertsIfArrayTooLarge() public {
        uint256[] memory bigClaims = new uint256[](101);
        vm.expectRevert(Gorra.InvalidArray.selector);
        vm.prank(admin);
        token.setRequiredClaims(bigClaims);
    }

    // --- View helpers ---

    function test_getRequiredClaims() public view {
        uint256[] memory claims = token.getRequiredClaims();
        assertEq(claims.length, 1);
        assertEq(claims[0], CLAIM_KYC);
    }

    function test_hasRequiredClaims_trueWhenClaimsPresent() public {
        _setupIdentityWithClaim(alice);
        assertTrue(token.hasRequiredClaims(alice));
    }

    function test_hasRequiredClaims_falseWhenNoIdentity() public view {
        assertFalse(token.hasRequiredClaims(charlie));
    }
}

