// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import {BaseTest} from "./BaseTest.t.sol";
import {Token} from "../src/Token.sol";
import {TokenFactory} from "../src/factories/TokenFactory.sol";
import {IAccessControl} from "@openzeppelin/contracts/access/IAccessControl.sol";

contract TokenFactoryTest is BaseTest {
    address internal newFactory = makeAddr("newFactory");

    // --- deployToken ---

    function test_deployToken_success() public {
        uint256[] memory claims = new uint256[](1);
        claims[0] = CLAIM_KYC;

        vm.prank(admin);
        address tokenAddr = tokenFactory.deployToken("My Token", "MTK", admin, enforcer, claims);

        assertTrue(tokenAddr != address(0));
        Token deployed = Token(tokenAddr);
        assertEq(deployed.name(), "My Token");
        assertEq(deployed.symbol(), "MTK");
        assertTrue(deployed.hasRole(deployed.DEFAULT_ADMIN_ROLE(), admin));
        assertTrue(deployed.hasRole(deployed.MINTER_ROLE(), enforcer));
    }

    function test_deployToken_emitsEvent() public {
        uint256[] memory claims = new uint256[](1);
        claims[0] = CLAIM_KYC;

        // We can't predict the token address, so only check indexed fields
        vm.expectEmit(false, true, false, false, address(tokenFactory));
        emit TokenFactory.TokenCreated(address(0), admin, "My Token", "MTK", claims, 0);
        vm.prank(admin);
        tokenFactory.deployToken("My Token", "MTK", admin, enforcer, claims);
    }

    function test_deployToken_defaultAdminFallsToSender() public {
        uint256[] memory claims = new uint256[](0);

        vm.prank(admin);
        address tokenAddr = tokenFactory.deployToken("My Token", "MTK", address(0), enforcer, claims);

        Token deployed = Token(tokenAddr);
        assertTrue(deployed.hasRole(deployed.DEFAULT_ADMIN_ROLE(), admin));
    }

    function test_deployToken_revertsIfNotAdmin() public {
        uint256[] memory claims = new uint256[](0);

        vm.expectRevert(abi.encodeWithSelector(
            IAccessControl.AccessControlUnauthorizedAccount.selector,
            alice,
            tokenFactory.FACTORY_ADMIN_ROLE()
        ));
        vm.prank(alice);
        tokenFactory.deployToken("My Token", "MTK", admin, enforcer, claims);
    }

    function test_deployToken_revertsIfEmptyName() public {
        uint256[] memory claims = new uint256[](0);

        vm.expectRevert(TokenFactory.EmptyString.selector);
        vm.prank(admin);
        tokenFactory.deployToken("", "MTK", admin, enforcer, claims);
    }

    function test_deployToken_revertsIfEmptySymbol() public {
        uint256[] memory claims = new uint256[](0);

        vm.expectRevert(TokenFactory.EmptyString.selector);
        vm.prank(admin);
        tokenFactory.deployToken("My Token", "", admin, enforcer, claims);
    }

    function test_deployToken_revertsIfZeroEnforcer() public {
        uint256[] memory claims = new uint256[](0);

        vm.expectRevert(abi.encodeWithSelector(
            TokenFactory.InvalidAddress.selector,
            "Enforcer cannot be zero address"
        ));
        vm.prank(admin);
        tokenFactory.deployToken("My Token", "MTK", admin, address(0), claims);
    }

    function test_deployToken_revertsIfClaimsArrayTooLarge() public {
        uint256[] memory bigClaims = new uint256[](101);

        vm.expectRevert(TokenFactory.ArrayTooLarge.selector);
        vm.prank(admin);
        tokenFactory.deployToken("My Token", "MTK", admin, enforcer, bigClaims);
    }

    // --- updateIdentityFactory ---

    function test_updateIdentityFactory() public {
        vm.prank(admin);
        tokenFactory.updateIdentityFactory(newFactory);

        assertEq(tokenFactory.identityFactory(), newFactory);
    }

    function test_updateIdentityFactory_emitsEvent() public {
        address oldFactory = tokenFactory.identityFactory();

        vm.expectEmit(true, true, false, false, address(tokenFactory));
        emit TokenFactory.IdentityFactoryUpdated(oldFactory, newFactory);
        vm.prank(admin);
        tokenFactory.updateIdentityFactory(newFactory);
    }

    function test_updateIdentityFactory_revertsIfSameFactory() public {
        address current = tokenFactory.identityFactory();

        vm.expectRevert(abi.encodeWithSelector(
            TokenFactory.InvalidAddress.selector,
            "New factory same as current"
        ));
        vm.prank(admin);
        tokenFactory.updateIdentityFactory(current);
    }

    function test_updateIdentityFactory_revertsIfZeroAddress() public {
        vm.expectRevert(abi.encodeWithSelector(
            TokenFactory.InvalidAddress.selector,
            "New identity factory cannot be zero address"
        ));
        vm.prank(admin);
        tokenFactory.updateIdentityFactory(address(0));
    }

    function test_updateIdentityFactory_revertsIfNotAdmin() public {
        vm.expectRevert(abi.encodeWithSelector(
            IAccessControl.AccessControlUnauthorizedAccount.selector,
            alice,
            tokenFactory.DEFAULT_ADMIN_ROLE()
        ));
        vm.prank(alice);
        tokenFactory.updateIdentityFactory(newFactory);
    }
}

test/integration/FullFlow.t.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

import {Test} from "forge-std/Test.sol";
import {ClaimIssuerManager} from "../../src/identity/ClaimIssuerManager.sol";
import {IdentityFactory} from "../../src/identity/IdentityFactory.sol";
import {Identity} from "../../src/identity/Identity.sol";
import {TokenFactory} from "../../src/factories/TokenFactory.sol";
import {Token} from "../../src/Token.sol";
import {Gorra} from "../../src/identity/Gorra.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

contract FullFlowTest is Test {
    uint256 internal constant CLAIM_KYC = 1;

    address internal deployer = makeAddr("deployer");
    address internal enforcer = makeAddr("enforcer");
    address internal alice = makeAddr("alice");
    address internal bob = makeAddr("bob");
    address internal charlie = makeAddr("charlie");

    ClaimIssuerManager internal claimIssuerManager;
    IdentityFactory internal identityFactory;
    TokenFactory internal tokenFactory;
    Token internal token;

    function setUp() public {
        // Step 1-2: Deploy core infrastructure (mirrors deployFactory.sol script)
        claimIssuerManager = new ClaimIssuerManager(deployer);

        vm.prank(deployer);
        identityFactory = new IdentityFactory(deployer, address(claimIssuerManager));

        vm.prank(deployer);
        tokenFactory = new TokenFactory(address(identityFactory));

        // Step 3: Wire factories together
        vm.startPrank(deployer);
        claimIssuerManager.addTokenFactory(address(tokenFactory));
        identityFactory.grantRole(identityFactory.IDENTITY_FACTORY_ADMIN(), address(tokenFactory));

        // Step 4: Register deployer as a claim issuer for CLAIM_KYC
        uint256[] memory issuerClaims = new uint256[](1);
        issuerClaims[0] = CLAIM_KYC;
        claimIssuerManager.addClaimIssuer(deployer, issuerClaims);
        vm.stopPrank();

        // Step 5: Deploy token via factory
        uint256[] memory requiredClaims = new uint256[](1);
        requiredClaims[0] = CLAIM_KYC;
        vm.prank(deployer);
        address tokenAddr = tokenFactory.deployToken(
            "Argy RWA",
            "ARWA",
            deployer,
            enforcer,
            requiredClaims
        );
        token = Token(tokenAddr);
    }

    function test_fullFlow_happyPath() public {
        // Step 6: Create identity for alice and issue KYC claim
        vm.prank(deployer);
        address aliceIdentity = identityFactory.createIdentity(alice);
        vm.prank(deployer);
        Identity(aliceIdentity).addClaim(CLAIM_KYC);

        // Step 7: Mint tokens to alice
        vm.prank(enforcer);
        token.mint(alice, 1000e18);
        assertEq(token.balanceOf(alice), 1000e18);

        // Step 8: Create identity for bob and issue KYC claim
        vm.prank(deployer);
        address bobIdentity = identityFactory.createIdentity(bob);
        vm.prank(deployer);
        Identity(bobIdentity).addClaim(CLAIM_KYC);

        // Step 9: alice transfers to bob — both have identity + claims
        vm.prank(alice);
        token.transfer(bob, 200e18);
        assertEq(token.balanceOf(alice), 800e18);
        assertEq(token.balanceOf(bob), 200e18);
    }

    function test_fullFlow_charlieNoIdentityCannotReceive() public {
        vm.prank(deployer);
        address aliceIdentity = identityFactory.createIdentity(alice);
        vm.prank(deployer);
        Identity(aliceIdentity).addClaim(CLAIM_KYC);
        vm.prank(enforcer);
        token.mint(alice, 1000e18);

        // charlie has no identity — transfer to him must fail
        vm.expectRevert(abi.encodeWithSelector(
            Gorra.InvalidAddress.selector,
            "Recipient has no identity"
        ));
        vm.prank(alice);
        token.transfer(charlie, 100e18);
    }

    function test_fullFlow_pauseBlocksAllTransfers() public {
        vm.prank(deployer);
        address aliceIdentity = identityFactory.createIdentity(alice);
        vm.prank(deployer);
        Identity(aliceIdentity).addClaim(CLAIM_KYC);
        vm.prank(deployer);
        address bobIdentity = identityFactory.createIdentity(bob);
        vm.prank(deployer);
        Identity(bobIdentity).addClaim(CLAIM_KYC);

        vm.prank(enforcer);
        token.mint(alice, 1000e18);

        // Pause
        vm.prank(enforcer);
        token.pause();

        vm.expectRevert(Pausable.EnforcedPause.selector);
        vm.prank(alice);
        token.transfer(bob, 100e18);

        // Unpause — transfer succeeds
        vm.prank(enforcer);
        token.unpause();

        vm.prank(alice);
        token.transfer(bob, 100e18);
        assertEq(token.balanceOf(bob), 100e18);
    }

    function test_fullFlow_multiWalletIdentityLinking() public {
        // alice creates identity, links a second wallet (e.g. hardware wallet)
        vm.prank(deployer);
        address aliceIdentity = identityFactory.createIdentity(alice);
        vm.prank(deployer);
        Identity(aliceIdentity).addClaim(CLAIM_KYC);

        // Link charlie as alice's second wallet
        vm.prank(deployer);
        identityFactory.linkWallet(aliceIdentity, charlie);

        // Mint to alice's primary wallet
        vm.prank(enforcer);
        token.mint(alice, 500e18);

        // charlie also has identity+claim via linked identity — mint to him succeeds
        vm.prank(enforcer);
        token.mint(charlie, 300e18);
        assertEq(token.balanceOf(charlie), 300e18);
    }

    function test_fullFlow_claimRevocationBlocksTransfer() public {
        vm.prank(deployer);
        address aliceIdentity = identityFactory.createIdentity(alice);
        vm.prank(deployer);
        Identity(aliceIdentity).addClaim(CLAIM_KYC);
        vm.prank(deployer);
        address bobIdentity = identityFactory.createIdentity(bob);
        vm.prank(deployer);
        Identity(bobIdentity).addClaim(CLAIM_KYC);

        vm.prank(enforcer);
        token.mint(alice, 1000e18);

        // Revoke alice's KYC claim
        vm.prank(deployer);
        Identity(aliceIdentity).removeClaim(CLAIM_KYC);

        // alice can no longer transfer
        vm.expectRevert(Gorra.InsufficientPermissions.selector);
        vm.prank(alice);
        token.transfer(bob, 100e18);
    }
